<section class="inner-hero admissions-hero"><div class="container"><a class="back-link light" href="<?= url('admissions') ?>">← All admission cycles</a><span class="eyebrow eyebrow-light"><?= e(ucwords(str_replace('_',' ',$cycle['effective_status']))) ?> admission</span><h1><?= e($cycle['name']) ?></h1><p><?= e($cycle['summary']?:'Review the configured programmes, dates, requirements and fees before applying.') ?></p><div class="inner-hero-actions"><?php if(in_array($cycle['effective_status'],['live','closing_soon'],true)):?><a class="button button-gold" href="<?= auth_user()?url('admissions/'.$cycle['slug'].'/apply'):url('register?cycle='.rawurlencode($cycle['slug'])) ?>">Apply now</a><?php else:?><span class="button button-ghost">Applications open <?= format_date($cycle['starts_at'],true) ?></span><?php endif?><?php if($cycle['prospectus_path']):?><a class="button button-ghost" href="<?= url('admissions/'.$cycle['slug'].'/prospectus') ?>">Download prospectus</a><?php endif?></div></div></section>
<section class="admission-summary"><div class="container"><div><span>Status</span><b><?= e(ucwords(str_replace('_',' ',$cycle['effective_status']))) ?></b></div><div><span>Opening</span><b><?= format_date($cycle['starts_at'],true) ?></b></div><div><span>Deadline</span><b><?= format_date($cycle['ends_at'],true) ?></b></div><div><span>Session</span><b><?= e($cycle['session_name']) ?></b></div></div></section>
<section class="section"><div class="container"><div class="section-heading split-heading"><div><span class="eyebrow">Programme choices</span><h2>Choose and rank your preferences</h2></div><p>Availability, eligibility and fees are validated again by the server when the application is submitted.</p></div><div class="programme-grid"><?php foreach($programs as $program):?><article class="programme-card"><div class="programme-copy"><span><?= e($program['award_type']) ?></span><h3><?= e($program['name']) ?></h3><p><?= e($program['summary']) ?></p><ul><li><?= e(rtrim(rtrim((string)$program['duration_years'],'0'),'.')) ?> years</li><li><?= number_format((int)$program['seat_capacity']) ?> configured seats</li><li><?= number_format((int)$program['available_seats']) ?> currently unallocated</li></ul><div class="programme-meta"><span><small>Application fee</small><b><?= money($program['application_fee']) ?></b></span><span><small>Admission fee</small><b><?= money($program['admission_fee']) ?></b></span></div><?php if(in_array($cycle['effective_status'],['live','closing_soon'],true)):?><a class="button button-primary" href="<?= auth_user()?url('admissions/'.$cycle['slug'].'/apply?program='.rawurlencode($program['program_slug'])):url('register?cycle='.rawurlencode($cycle['slug']).'&program='.rawurlencode($program['program_slug'])) ?>">Apply for this programme</a><?php endif?></div></article><?php endforeach?></div></div></section>
<section class="section eligibility-section"><div class="container detail-layout"><div><span class="eyebrow">Applicant instructions</span><h2>Read before submitting.</h2><div class="prose-content"><?= nl2br(e($cycle['instructions'])) ?></div><div class="compliance-callout"><b>Declaration</b><p><?= e($cycle['declaration_text']) ?></p></div></div><aside class="document-list"><h3>Configured document checklist</h3><?php foreach($requirements as $requirement):?><div><span class="doc-icon">▤</span><span><b><?= e($requirement['name']) ?></b><small><?= e(ucfirst($requirement['stage'])) ?> · <?= $requirement['is_required']?'Required':'If applicable' ?><?= $requirement['program_name']?' · '.$requirement['program_name']:'' ?><?= $requirement['category']?' · '.$requirement['category']:'' ?></small></span></div><?php endforeach?><p>Each document's accepted MIME types and maximum size are enforced by the server.</p></aside></div></section>
